def match(orders):
    import heapq

    buy_heap = []   # entries: (-price, seq, id)
    sell_heap = []  # entries: (price, seq, id)
    book = {}       # id -> dict(side, price, qty, seq)
    seq_counter = 0
    trades = []

    def add_resting(id, side, price, qty, seq):
        book[id] = {'side': side, 'price': price, 'qty': qty, 'seq': seq}
        if side == 'buy':
            heapq.heappush(buy_heap, (-price, seq, id))
        else:
            heapq.heappush(sell_heap, (price, seq, id))

    def top_valid(heap):
        while heap:
            item = heap[0]
            oid = item[2]
            if oid in book and book[oid]['qty'] > 0:
                return item
            heapq.heappop(heap)
        return None

    for order in orders:
        typ = order[0]
        if typ == 'cancel':
            oid = order[1]
            if oid in book:
                del book[oid]
            continue

        seq_counter += 1
        seq = seq_counter

        if typ == 'limit':
            _, id_, side, price, qty = order
        elif typ == 'ioc':
            _, id_, side, price, qty = order
        elif typ == 'market':
            _, id_, side, qty = order
            price = None
        else:
            continue

        remaining = qty
        opp_heap = sell_heap if side == 'buy' else buy_heap

        while remaining > 0:
            top = top_valid(opp_heap)
            if top is None:
                break

            if side == 'buy':
                opp_actual_price = top[0]
            else:
                opp_actual_price = -top[0]

            if typ == 'market':
                cross = True
            else:
                if side == 'buy':
                    cross = price >= opp_actual_price
                else:
                    cross = price <= opp_actual_price

            if not cross:
                break

            opp_id = top[2]
            opp_order = book[opp_id]
            trade_qty = min(remaining, opp_order['qty'])
            trade_price = opp_actual_price

            if side == 'buy':
                trades.append([id_, opp_id, trade_price, trade_qty])
            else:
                trades.append([opp_id, id_, trade_price, trade_qty])

            remaining -= trade_qty
            opp_order['qty'] -= trade_qty

            if opp_order['qty'] == 0:
                del book[opp_id]
                heapq.heappop(opp_heap)

        if typ == 'limit' and remaining > 0:
            add_resting(id_, side, price, remaining, seq)

    return trades

